#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the owner's one-time jobs, run on the build machine from the
# repository's top folder. `scripts/owner-setup.sh 6` starts at stage 6
# (Google's identity check can take days, so the last stages often wait).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
FROM="${1:-1}"
cd "$(dirname "$0")/.."

RELEASE_KEY="${FREESIZE_RELEASE_KEY:-$HOME/.freesize/release-key}"
KEYSTORE="${DISKTREE_KEY_DIR:-$HOME/.android}/disktree-release.keystore"
PACKAGE="io.github.mcgeaverbeaver.freesize"
REPO_URL="https://github.com/McGeaverBeaver/FreeSize"
PUBLIC_HALF=""

# skip N: true when stage N comes before the one asked to start at; it
# still counts the stage so the numbers stay right.
skip() {
  if (( $1 < FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 0; fi
  return 1
}

banner "FreeSize: the owner's one-time jobs"

# ── 1 ─────────────────────────────────────────────────────────────────────
if ! skip 1; then
stage "Make the release key"
say "The release key signs every release's SHA256SUMS.txt, so the apps only"
say "install updates that came from this machine. Its private half stays in"
say "$RELEASE_KEY and is never printed or committed."

if [[ -f "$RELEASE_KEY" ]]; then
  note "It exists already, so nothing is made. Moving on."
else
  confirm "Make it now (builds the command line first if needed)?" || { warn "stopped"; exit 1; }
  cargo build -q --release -p freesize-cli
  out=$(target/release/freesize release key "$RELEASE_KEY")
  printf '%s\n' "$out" | sed 's/^/  /'
  PUBLIC_HALF=$(printf '%s\n' "$out" | sed -n '/^Public half/{n;p;}')
fi
pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if ! skip 2; then
stage "Put the public half in the repository"
# Commits and pushes the key file, making sure git knows who's committing
# first (a fresh VM doesn't, and the commit then fails). Says what failed.
push_public_key() {
  if [[ -z "$(git config user.email)" ]]; then
    say "Git doesn't know who you are yet. The repository is public, so use"
    say "GitHub's noreply address rather than your own email."
    git config --global user.name "McGeaverBeaver"
    git config --global user.email "29310945+McGeaverBeaver@users.noreply.github.com"
    note "set git's name and email to McGeaverBeaver's GitHub noreply address"
  fi
  git add release/public-key.txt &&
    git commit -q -m "The release key's public half" &&
    git pull -q --rebase origin master &&
    git push -q origin master
}

if grep -qvE '^\s*(#|$)' release/public-key.txt; then
  note "release/public-key.txt already holds a key:"
  grep -vE '^\s*(#|$)' release/public-key.txt | sed 's/^/    /'
  if [[ -n "$(git status --porcelain release/public-key.txt)" ]] ||
     ! git diff --quiet origin/master -- release/public-key.txt 2>/dev/null; then
    say "It isn't on GitHub yet."
    if confirm "Commit and push it to master now?"; then
      if push_public_key; then
        printf '  %s✓ pushed%s\n' "$GREEN" "$RESET"
      else
        say "The commit or push failed (see above); tell Claude what it said."
        SKIPPED+=("commit and push release/public-key.txt")
      fi
    else
      SKIPPED+=("commit and push release/public-key.txt")
    fi
  fi
else
  if [[ -z "$PUBLIC_HALF" ]]; then
    say "The key was made on an earlier run; copy its public half from that"
    say "run's output (the line under \"Public half, for release/public-key.txt\")."
    ask PUBLIC_HALF "Paste the public half (one base64 line):"
  fi
  printf '%s\n' "$PUBLIC_HALF" >> release/public-key.txt
  git --no-pager diff release/public-key.txt
  if confirm "Commit and push this to master?"; then
    if push_public_key; then
      printf '  %s✓ pushed%s\n' "$GREEN" "$RESET"
    else
      say "The commit or push failed (see above); tell Claude what it said."
      SKIPPED+=("commit and push release/public-key.txt")
    fi
  else
    SKIPPED+=("commit and push release/public-key.txt")
  fi
fi
note "From the next release on, release.sh signs the sums file."
pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if ! skip 3; then
stage "Back up the keys"
say "Losing either key means nobody can ship an update that installs over"
say "FreeSize. Copy these files somewhere safe (a password manager, a USB"
say "stick). The wizard doesn't show what's in them."
step "$RELEASE_KEY"
step "$KEYSTORE"
step "$KEYSTORE.password"
for f in "$RELEASE_KEY" "$KEYSTORE" "$KEYSTORE.password"; do
  [[ -f "$f" ]] || warn "missing: $f"
done
pause "Press Enter once all three are backed up"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if ! skip 4; then
stage "Two-factor sign-in on GitHub"
say "Community Applications wants it on the account the repository belongs to."
open_url "https://github.com/settings/security"
step "Under Two-factor authentication: if it says Enabled, you're done."
step "Otherwise, Enable two-factor authentication and follow GitHub's steps."
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if ! skip 5; then
stage "Submit to Community Applications"
say "CA reads unraid/ca/ca_profile.xml, the plugin's unraid/ca/freesize.xml"
say "and the Hub's unraid/freesize-hub.xml from the repository."
open_url "https://ca.unraid.net/submit/new"
step "Sign in if it asks, and give the repository: $REPO_URL"
step "Run Validate, then Scan. Both should find the plugin and the Hub."
step "If either complains, Ctrl-C and tell Claude what it said."
step "Submit. Its progress shows under My submissions (ca.unraid.net/submissions)."
note "If the reviewers ask for a forum support thread, tell Claude its address:"
note "it goes into the plugin's entry and freesize.plg."
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if ! skip 6; then
stage "Google: register as the developer"
say "Android is starting to block apps from unregistered developers, even"
say "when they're installed from a file. Registering FreeSize's package"
say "removes the block for everyone."
open_url "https://android.google.com/developerconsole/developers"
step "Sign in with the Google account that should own FreeSize."
step "Pick the account type and distribution Google offers (read its fees"
step "and checks there; a hobbyist type with fewer checks exists)."
step "Complete the identity check."
note "The check can take days. Once Google says you're verified, run:"
note "  scripts/owner-setup.sh 7"
if ! confirm "Are you verified already?"; then
  SKIPPED+=("stages 7 and 8, once Google has verified you: scripts/owner-setup.sh 7")
  finish
  exit 0
fi
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if ! skip 7; then
stage "Google: register the package name"
if [[ ! -f "$KEYSTORE" || ! -f "$KEYSTORE.password" ]]; then
  warn "no signing key at $KEYSTORE; build the APK once first"; exit 1
fi
FINGERPRINT=$(KS_PASS="$(cat "$KEYSTORE.password")" keytool -list -v \
  -keystore "$KEYSTORE" -alias release -storepass:env KS_PASS \
  | sed -n 's/^[[:space:]]*SHA256: //p')
say "Package name:            $BOLD$PACKAGE$RESET"
say "Signing key fingerprint: $BOLD$FINGERPRINT$RESET"
note "(the fingerprint is public: it's in every APK)"
open_url "https://android.google.com/developerconsole/developers"
step "Packages → Register package name."
step "Enter the package name above, friendly name FreeSize, then Next."
step "Select key: pick the fingerprint above (or paste it), then Add key."
step "Select Upload APK and copy the snippet it shows. Leave the page open."
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if ! skip 8; then
stage "Google: prove the package is ours"
say "Google wants an APK signed with FreeSize's key that carries its snippet"
say "in assets/adi-registration.properties."
proof_dir=$(mktemp -d)
say "Paste the snippet, then press Enter and Ctrl-D:"
cat > "$proof_dir/adi-registration.properties"
[[ -s "$proof_dir/adi-registration.properties" ]] || { warn "nothing pasted"; exit 1; }
note "Building the APK with it (several minutes)…"
mkdir -p dist
FREESIZE_APK_EXTRA_ASSET="$proof_dir/adi-registration.properties" \
  scripts/android/build-apk.sh dist/freesize-google-proof.apk
rm -rf "$proof_dir"
say "Built: $BOLD$PWD/dist/freesize-google-proof.apk$RESET"
step "Back on Google's page, Upload, and pick that file."
step "Google emails when the package is registered; Packages then says Registered."
note "The proof APK is only for Google; delete it after the upload."
pause
fi

finish
